    const Repetido = (pos,lista, valores)=>{
        let cantidad=0;
        while (true) {
            const p = lista.indexOf(valores[pos+cantidad].field)
            if (p===-1 && valores[pos+cantidad].field.indexOf('nota-')!==-1){
                break
            }else if (valores[pos+cantidad].field.indexOf('nota-')===-1){
                cantidad=-1;
                break
            }else{
                cantidad+=1
            }
        }
        
        return cantidad
    }
